def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0
                            and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            components.append(cells)
    if components:
        sizes = [len(cells) for cells in components]
        largest, smallest = max(sizes), min(sizes)
        for cells, size in zip(components, sizes):
            if size == largest:
                color = 8
            elif size == smallest:
                color = 7
